sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    console.error(">>>>>Detail data - Fetch success:", event);
    debugger;
    if (!api.state.dataLoaded) {
        // Data Resourceから初めて読み込むとき
        console.debug(">>> api.state.records.length was 0");
        // debugger;

        var res = api.data.look_up_detail_data.results;
        if (!res) {
            throw new Error("Look up Detail Data: Null?");
            return;
        }

        /**
            取得データの修正。変更。元データの構造がUIと不一致なので
        */
        res = res.map(rec => {
            rec.checked = false;

            /**
             * issue_date.valueは、ServiceNowのUTC時刻なので、JST時刻に変更している。
             　データ更新時にvalueを使ってsetDisplayValue()している
             * UTC時刻は、utcDateに設定している。
             */
            rec.issue_date = {
                ...rec.issue_date,
                utcDate: rec.issue_date.value,
                // value: rec.issue_date.displayValue.replace(" ", "T") + "+09:00",
                isoDate: rec.issue_date.displayValue.replace(" ", "T") + "+09:00",
                // yyyymm: rec.issue_date.displayValue.slice(0,7),
                // dd: rec.issue_date.displayValue.slice(8,10)
            };

            rec.employee.selected = true;

            // 所属|役職名|担当名
            rec.departmentArray = [];
            for (var i = 1; i < 7; i++) {
                let objDept = {
                    "dept": {
                        "value": rec["dept_id" + i] ? rec["dept_id" + i].value : "",
                        "displayValue": rec["dept_name" + i] ? rec["dept_name" + i].value : ""
                    },
                    "position": {
                        "value": rec["position" + i] ? rec["position" + i].value : "",
                        "displayValue": rec["position_name" + i] ? rec["position_name" + i].value : ""
                    },
                    "tanto": {
                        "value": rec["tanto" + i] ? rec["tanto" + i].value : "",
                        "displayValue": rec["tanto" + i] ? rec["tanto" + i].value : ""
                    },
                    "visible": rec["dept_id" + i] && rec["dept_id" + i].value ? true : false
                };
                if (i==1 || objDept.dept.value || objDept.dept.displayValue || objDept.position.value || objDept.position.displayValue || objDept.tanto.value || objDept.tanto.displayValue)

                    rec.departmentArray.push(objDept);

                // 不要項目削除
                delete rec["dept_id" + i];
                delete rec["dept_name" + i];
                delete rec["position" + i];
                delete rec["position_name" + i];
                delete rec["tanto" + i];
            }

            ["location", "job_grade", "role_grade", "vu"].forEach(v => {
                rec[v] = {
                    value: rec[v + "_id"].value,
                    displayValue: rec[v + "_name"].value
                };
            });

            // Option Array
            /**
             * Optionsの型に応じて、値の変換処理が必要。
             * 特に、BooleanであるCheckBox
             */
            rec.opt = [];
            for (let i = 0; i < 5; i++) {
                let optType = api.state.options[i] && api.state.options[i].type || "";
                let val = rec["opt" + (i+1)].value || "";
                let displayVal = rec["opt" + (i+1)].displayValue || "";
                if (optType == "checkbox") {
                    val = val == "true" ? true : val == "false" ? false : "";
                    displayVal = val;
                }

                rec.opt.push({
                    value: val,
                    displayValue: displayVal
                });

                // 削除
                delete rec["opt" + (i+1)];
            }

            // 備考
            if (rec.remarks.value == "ZZ") {
                rec.remarks.displayValue = rec.remarks_name.value;
                rec.remarks.useCustom = true;
            }
            delete rec.remarks_name;
            //
            return rec;
        });

        api.setState("records", res);
        api.setState("dataLoaded", true);

        // api.data.look_up_gaudi.refresh();
        // api.data.look_up_department.refresh();

    }
}
